for flip in (1,-1):
 for k in range(4):
  arr=[]
  for r,c in pts:
   x,y=r, c*flip
   for _ in range(k): x,y=y,-x
   arr.append((x,y))
  mr=min(x for x,y in arr); mc=min(y for x,y in arr)
  forms.add(tuple(sorted((x-mr,y-mc) for x,y in arr)))
